#!/bin/sh
# flow.sh: one step of the Omega merge queue for one Radicle repository.
# Generated by tools/flow.om from the repository's open patches and its receipt ledger; do not
# edit by hand.
#
# A patch merges only as a fast-forward of the default branch, and only when a receipt says the
# default branch's gate passed on the patch head's exact tree, so the default branch only ever
# moves to a tree that passed the gate guarding it. A patch whose tree has no receipt is gated:
# the default branch's build.sh, never the patch's own, runs in a worktree of the patch head,
# and the verdict goes into the ledger and onto the patch as a comment. A tree is gated once,
# however many patches carry it, and never again while the gate is unchanged.
#
#   sh flow.sh REPO DEFAULT RECEIPTS
# REPO      a Radicle working copy, fetched, with its delegate's key authenticated (rad auth)
# DEFAULT   the name of its default branch
# RECEIPTS  the receipt ledger this plan was made from; new verdicts are appended to it
# Exit status: 0 the step ran; 1 the repository is not as planned, or a gate, comment or push
# could not run; 2 usage.
# Each patch's decision is one "# plan ACTION PATCH HEAD TREE" line, in the order of the input.
# plan-branch b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0
# plan-gate 9a7e777777777777777777777777777777777777
# plan-counts patches 0 merged 0 merge 0 queued 0 rebase 0 fail 0 gate 0 same 0

branch='b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0'
gate='9a7e777777777777777777777777777777777777'
set -eu
umask 022
[ $# -eq 3 ] || { echo 'usage: sh flow.sh REPO DEFAULT RECEIPTS' >&2; exit 2; }
repo=$1 def=$2 rec=$3
fl_die() { printf 'flow: %s\n' "$*" >&2; exit 1; }
fl_git() { git -C "$repo" "$@"; }
command -v git >/dev/null 2>&1 || fl_die "git is required"
command -v rad >/dev/null 2>&1 || fl_die "rad is required: https://radicle.xyz"
[ -f "$rec" ] || fl_die "no receipt ledger $rec"
cur=$(fl_git rev-parse --verify -q "refs/remotes/rad/$def^{commit}") || fl_die "$repo has no rad/$def"
[ "$cur" = "$branch" ] || fl_die "rad/$def is $cur, not $branch: make a new plan"
[ "$(fl_git rev-parse --verify -q "$branch:build.sh")" = "$gate" ] || fl_die "build.sh at $branch is not blob $gate"
fl_work=$(mktemp -d)
trap 'rm -rf "$fl_work"; fl_git worktree prune' EXIT
trap 'exit 1' HUP INT TERM
fl_tree() { # fl_tree PATCH HEAD TREE: HEAD must be a commit whose tree is TREE
  [ "$(fl_git rev-parse --verify -q "$2^{tree}")" = "$3" ] || fl_die "patch $1: $2 is not a commit with tree $3"
}
fl_gate() { # fl_gate PATCH HEAD TREE: run the default branch's build.sh on HEAD; record and post the verdict
  fl_tree "$@"
  w=$fl_work/$3
  fl_git worktree add -q --detach "$w" "$2" || fl_die "patch $1: cannot check out $2"
  fl_git cat-file blob "$gate" > "$w/build.sh"
  mkdir "$w.home"
  # the gate never sees the delegate's key: no RAD_PASSPHRASE, RAD_SECRET, RAD_HOME, SSH_AUTH_SOCK or HOME
  if (cd "$w" && env -u RAD_PASSPHRASE -u RAD_SECRET -u RAD_HOME -u SSH_AUTH_SOCK HOME="$w.home" sh ./build.sh) > "$w.log" 2>&1; then v=pass; else v=fail; fi
  l=$(sha256sum < "$w.log" | cut -c1-64)
  printf '%s\t%s\t%s\t%s\n' "$3" "$gate" "$v" "$l" >> "$rec"
  m="flow gate $v tree $3 gate $gate log $l"
  f=$(sed -n '/^FAIL/{p;q;}' "$w.log")
  [ -z "$f" ] || m="$m
$f"
  (cd "$repo" && rad patch comment "$1" -m "$m" > /dev/null) || fl_die "patch $1: cannot post the verdict"
  fl_git worktree remove --force "$w"
  printf 'flow: gate %s patch %s tree %s\n' "$v" "$1" "$3"
}
fl_merge() { # fl_merge PATCH HEAD TREE: fast-forward DEFAULT to HEAD, whose tree passed the gate
  fl_tree "$@"
  fl_git merge-base --is-ancestor "$branch" "$2" || fl_die "patch $1: $2 does not fast-forward $branch"
  fl_git push -q rad "$2:refs/heads/$def" || fl_die "patch $1: the push of $2 to $def was refused"
  printf 'flow: merged patch %s head %s\n' "$1" "$2"
}

echo 'flow: step done'
